        script.
            function escapeHtml(text) {
              var map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
              };
              return text.replace(/[&<>"']/g, function(m) { return map[m]; });
            }
            function parse_timestamp(s) {
            var match = s.match(/^(?:([0-9]+):)?([0-5][0-9]):([0-5][0-9](?:[.,][0-9]{0,3})?)/);
            if (match == null) {
            throw 'Invalid timestamp format: ' + s;
            }
            var hours = parseInt(match[1] || "0", 10);
            var minutes = parseInt(match[2], 10);
            var seconds = parseFloat(match[3].replace(',', '.'));
            return seconds + 60 * minutes + 60 * 60 * hours;
            }
            function quick_and_dirty_vtt_or_srt_parser(vtt) {
            var sanitizedVtt = escapeHtml(vtt);
            var lines = sanitizedVtt.trim().replace('\r\n', '\n').split(/[
]/).map(function(line) {
            return line.trim();
            });
            var cues = [];
            var start = null;
            var end = null;
            var payload = null;
            for (var i = 0; i < lines.length; i++) {
            if (lines[i].indexOf('-->') >= 0) {
            var splitted = lines[i].split(/[ \t]+-->[ \t]+/);
            if (splitted.length != 2) {
            throw 'Error when splitting "-->": ' + lines[i];
            }
            // Already ignoring anything past the "end" timestamp (i.e. cue settings).
            start = parse_timestamp(splitted[0]);
            end = parse_timestamp(splitted[1]);
            } else if (lines[i] == '') {
            if (start && end) {
            var cue = new VTTCue(start, end, payload);
            cues.push(cue);
            start = null;
            end = null;
            payload = null;
            }
            } else if(start && end) {
            if (payload == null) {
            payload = lines[i];
            } else {
            payload += '\n' + lines[i];
            }
            }
            }
            if (start && end) {
            var cue = new VTTCue(start, end, payload);
            cues.push(cue);
            }
            return cues;
            }
            function init() {
            var video = document.querySelector('video');
            var subtitle = document.getElementById('subtitle');
            var track = video.addTextTrack('subtitles', subtitle.dataset.label, subtitle.dataset.lang);
            track.mode = "showing";
            quick_and_dirty_vtt_or_srt_parser(subtitle.innerHTML).map(function(cue) {
            track.addCue(cue);
            });
            }
            init();"}],"justificativa_tecnica":"A vulnerabilidade ocorre porque o conteúdo do elemento <script id='subtitle'> é interpretado diretamente como legendas, podendo conter código malicioso. Ao aplicar a função escapeHtml no conteúdo antes do processamento, garantimos que caracteres especiais que poderiam ser interpretados como código HTML ou JavaScript sejam convertidos em entidades HTML seguras, impedindo a execução de scripts maliciosos. Isso mitiga o risco de XSS sem alterar a funcionalidade de exibição das legendas.","limitacoes_da_correcao":"A sanitização simples via escapeHtml pode não cobrir todos os casos complexos de formatação de legendas, podendo afetar a renderização correta de legendas que dependam de caracteres especiais. Além disso, a solução assume que o conteúdo das legendas é confiável ou que a sanitização é suficiente; para maior segurança, recomenda-se validar e sanitizar o conteúdo no backend antes de enviá-lo ao cliente."}
